 produce=mission('📓','Denuncie o boato','Conte a Pete que alguém espalha boatos, como no Burn Book de Mean Girls.','Use spreading rumors ou let it slip, e cite Mean Girls ou o Burn Book.','Like the Burn Book in Mean Girls, someone is spreading rumors, and she let it slip.',[('Usei spread rumors, let it slip ou hush up?',r'\b(spread(s|ing)? (a )?rumou?rs?|spread(s|ing)? rumou?rs|let it slip|let slip|hush(ed|ing)? (it )?up|go behind|went behind)\b','spreading rumors','Use spreading rumors, let it slip ou hush up.','Colocação: ótimo.'),('Falei de rumor, segredo ou escola?',r'\b(rumou?rs?|secret|school|principal|classmates?|friend|test)\b','rumors','Cite rumors, secret, school ou principal.','Tema: ótimo.'),('Citei Mean Girls ou o Burn Book?',r'\b(Mean Girls|Burn Book|Cady|Regina|Tina Fey)\b','Burn Book','Cite Mean Girls ou Burn Book.','Obra: ótimo.')],['Boato denunciado.','Cite Mean Girls ou o Burn Book.']),
 mission2=mission('🗡️','Conte o que aconteceu','Use uma expressão de segredos para contar uma traição.','Use spread rumors, hush up, let it slip ou go behind someone\'s back.',"She let it slip, went behind my back, and now they spread rumors.",[('Usei uma expressão do tema?',r'\b(spread(s|ing)? rumou?rs|spread rumou?rs|hush(es|ed|ing)? (it )?up|let it slip|went behind (my|his|her|our|their|your) back|go(es|ing)? behind (my|his|her|our|their|your) back)\b','let it slip','Use uma das quatro expressões.','Expressão: ótimo.'),('Falei de um amigo, colega ou irmã?',r'\b(she|he|they|friend|sister|brother|classmate|colleague)\b','She','Cite she, he, they, friend ou sister.','Pessoa: ótimo.'),('Usei and, now ou then?',r'\b(and|now|then|but|because)\b','and','Use and, now, then ou because.','Estrutura: ótimo.')],['Boa narrativa.','Cite quem espalhou.']),
